def parse_price(s: str) -> float:
    import re
    match = re.match(r'^\$([0-9,]+)\.?([0-9]{0,2})$', s)
    if not match:
        raise ValueError(f"Invalid price format: {s}")
    dollars = match.group(1).replace(',', '')
    cents = match.group(2) or '00'
    return float(f"{dollars}.{cents}")

